from checkpoint import *
K='krichever1978commutative'; S='sznagy1976diagonalization'; R='krichever1978rational'; D='drinfeld1977commutative'
begin(431)
item(431,'P000729-P000730','theorem','An algebraic relation between commuting ordinary differential operators',r'Krichever reports that the problem \([L_1,L_2]=0\) was treated by Burchnall and Chaundy in papers listed as 1922, 1928 and 1931.',r'If scalar ordinary differential operators \(L_1,L_2\) with locally analytic coefficients commute, their orders are positive and their leading coefficients are normalized to one, then there is a nonzero polynomial \(Q\in\mathbb C[\lambda,\mu]\) such that \(Q(L_1,L_2)=0\). Coprimality of the orders is not required for this algebraic-dependence statement.',r'\citet[Theorem~1.1 and its proof]{'+K+r'} explicitly attribute and prove the Burchnall--Chaundy theorem. This confirms an old result, not a new theorem of the 1977 seminar. The earlier occurrence 1975-374.2 concerns the same spectral-curve line.',[K],cls='E',area='Integrable systems',literal='correct with missing hypotheses')
item(431,'P000729-P000730','theorem','The rank-one spectral-curve description',r'The older work is said to have posed and solved the classification for scalar operators of relatively prime orders, using algebraic geometry.',r'A commuting rank-one ring of scalar ordinary differential operators is encoded by an algebraic spectral curve, a smooth marked point at infinity, a local parameter and rank-one sheaf data with a local trivialization. On a smooth curve in generic position this becomes a nonspecial divisor or line bundle; singular curves require torsion-free sheaves and cannot be omitted from an unrestricted classification.',r'\citet[introduction and \S1]{'+K+r'} confirm the local classification by Burchnall--Chaundy and distinguish it from the later effective reconstruction. This follows earlier seminar items 1975-374.5 and 1975-380.2; the latter\textquotesingle s smooth-curve-only scope remains a real qualification.',[K],cls='E',area='Integrable systems',reconstruction=r'The marked-point and sheaf data spell out what a modern classification needs; they are not all enumerated in this short announcement.',match='partial')
item(431,'P000729-P000730','method','Theta formulas and linear motion on a Jacobian',r'The historical construction is described as insufficiently effective: no theta functions, no straight-line Jacobian motion, and no recognition of conditional periodicity.',r'For nonsingular rank-one spectral data, the Baker--Akhiezer construction yields explicit theta-function formulas and linearizes the commuting flows on the Jacobian. Quasiperiodicity and smooth real solutions require additional reality and nonsingularity assumptions; they do not hold for arbitrary complex or singular data.',r'\citet[introduction, \S1 and \S2]{'+K+r'} make the historical distinction and supply effective reconstruction, while acknowledging serious errors in the earlier higher-rank implementation. The notebook\textquotesingle s historical assessment is thus independently documented by the speaker\textquotesingle s published account.',[K],cls='A',area='Integrable systems',match='partial')
item(431,'P000730','remark','Unspecified historical reference and almost-commuting pairs',r'A 1939 paper is said to omit the older references, followed by the fragment that almost-commuting operators and Lax pairs exist.',r'The author, title and equation of the 1939 paper are absent. The phrase almost commuting specifies neither a commutator nor a deformation parameter, so no definite mathematical proposition can be reconstructed from it.',r'Comparison with \citet[introduction and bibliography]{'+K+r'} identifies the Burchnall--Chaundy line but does not resolve these two notebook fragments. No exact later result is assigned to them.',[K],cls='F',area='Integrable systems',literal='not determinable',match='none found',verification='unresolved lead',confidence='low',status='As of 10 November 2026, these fragments remain unidentified; this is a source-identification limit, not evidence of an undeveloped mathematical problem.')
save()
begin(433)
item(433,'P000735','definition','Bounded analytic and inner functions',r'\(H^\infty\) is the algebra of bounded analytic functions on the disk; inner functions have boundary modulus one almost everywhere.',r'\(H^\infty(\mathbb D)\) consists of bounded holomorphic functions on the unit disk. An inner function has radial boundary values of modulus one for Lebesgue-almost every boundary point. The notation means \(|u(e^{it})|=1\), not multiplication of \(u\) by \(e^{it}\).',r'\citet[\S1, opening definitions]{'+S+r'} use precisely this setting, before the November 1977 talk.',[S],area='Complex and operator analysis',literal='correct')
item(433,'P000735-P000736','theorem','Canonical factorization and the singular inner factor',r'A bounded analytic function is decomposed as an inner factor times an outer factor, and the inner factor as a Blaschke product times an exponential built from a singular measure.',r'Every nonzero \(u\in H^\infty\) has an inner--outer factorization. Its inner part is, up to a unimodular constant, a Blaschke product times \(S_\mu(z)=\exp\{-\int_{0}^{2\pi}(e^{it}+z)(e^{it}-z)^{-1}\,d\mu(t)\}\), for a finite positive singular measure \(\mu\). A positive exponent with positive measure gives the reciprocal and is generally unbounded.',r'\citet[\S1 and the proof of Lemma~2]{'+S+r'} invoke canonical factorization. The minus sign omitted in the notebook is mathematically necessary for the stated class.',[S],area='Complex and operator analysis',literal='false as written',match='partial',development='annotated')
item(433,'P000735-P000736','definition','Greatest common inner divisor',r'The wedge \(\bigwedge_\alpha u_\alpha\) is described by a product over zeros and the lower bound of the singular measures.',r'The greatest common inner divisor of a family of nonzero bounded analytic functions is determined, up to a unimodular factor, by the minimum zero multiplicities at each point and the greatest common lower bound of the singular measures of their inner factors. Zeros belonging to only one member do not contribute. For an all-zero family a separate convention is needed.',r'\citet[\S1]{'+S+r'} explicitly define the divisor for \(H^\infty\) families and use the all-zero value zero.',[S],area='Complex and operator analysis')
item(433,'P000736','claim','Failure of an unrestricted Bézout identity in H-infinity',r'The notes deny that the greatest common inner divisor always has the form \(xu+yv\) with \(x,y\in H^\infty\).',r'Having no common nonconstant inner divisor does not imply that \(xu+yv=1\) has bounded analytic solutions. Such an identity forces \(\inf_{z\in\mathbb D}(|u(z)|+|v(z)|)>0\), a condition stronger than inner coprimality. Thus \(H^\infty\) is not a Bézout domain in this sense.',r'\citet[introduction and \S3]{'+S+r'} explain why ordinary matrix equivalence must be replaced by quasi-equivalence. This supports the algebraic obstruction; the notebook gives no explicit counterexample.',[S],area='Complex and operator analysis',literal='correct',match='partial')
item(433,'P000736','remark','The stronger outer-factor denial is not a complete statement',r'A second denied identity has an outer factor \(h\) on one side and a heavily crossed-out mark on the other.',r'The visible formula suggests a proposed Bézout identity after multiplication by an outer function, but its quantifiers, the crossed-out coefficient, and whether the factor is required to be invertible are not fixed. An exact strengthened negative assertion cannot be supplied responsibly.',r'\citet[\S1, Lemma~2]{'+S+r'} give the precise weaker generic-combination statement used next, but do not identify this damaged displayed denial.',[S],area='Complex and operator analysis',cls='F',literal='not determinable',match='none found',verification='unresolved lead',confidence='low',status='As of 10 November 2026, only the following Sherman lemma is securely identified; the stronger denial remains ambiguous.')
item(433,'P000736','theorem','Sherman’s generic linear-combination lemma',r'For a fixed inner function \(\omega\), constants can be chosen so that \(u+tv=h_t(u\wedge v)\), with \(h_t\wedge\omega=1\); at most countably many \(t\) are exceptional.',r'If \(u,v\in H^\infty\) and \(\omega\) is inner, then for all but at most countably many complex \(t\), \(\omega\wedge(u+tv)=\omega\wedge u\wedge v\). Equivalently, after dividing \(u,v\) by their common inner divisor, the remaining linear combination is inner-coprime to \(\omega\) for generic \(t\).',r'Exactly \citet[\S1, Lemma~2, pp.224--225]{'+S+r'}, credited there to M. Sherman. The paper was received 1 November 1975 and published in 1976, so the talk is expository.',[S],area='Complex and operator analysis',literal='correct',problem='GP-1977-21')
item(433,'P000736','theorem','Finite polynomial combinations and simultaneous rows',r'The notes extend the lemma to \(u_1+t u_2+\cdots+t^{r-1}u_{r+1}\), and then to finitely many rows.',r'For a finite list \(u_1,\ldots,u_r\), divide by its common inner divisor. For any fixed inner \(\omega\), the polynomial combination \(u_1+t u_2+\cdots+t^{r-1}u_r\) is then inner-coprime to \(\omega\) outside a countable set of \(t\). One may avoid the union of the exceptional sets for finitely or countably many such rows. The last subscript in the notebook must be \(r\), not \(r+1\).',r'\citet[\S1, Lemma~2 and \S2, Main Lemma]{'+S+r'} establish the generic-combination mechanism and a stronger simultaneous \(\ell^1\)-coefficient theorem. The exact moment-curve wording in the notebook is a finite version; the paper\textquotesingle s Main Lemma does not insist on coefficients \(1,t,t^2,\ldots\).',[S],area='Complex and operator analysis',literal='false as written',match='partial',development='annotated',problem='GP-1977-21')
item(433,'P000736','method','Matrix reduction by controlled inner divisors',r'The final line mentions elementary transformations of a matrix.',r'The generic-combination lemma can select combinations of rows or columns with prescribed common inner divisors and supports a quasi-equivalence diagonalization theory for finite and semi-finite \(H^\infty\)-matrices. It does not provide a Smith normal form under arbitrary invertible \(H^\infty\) row and column operations, nor settle all doubly infinite matrices.',r'\citet[\S3]{'+S+r'} carry out this program and explicitly separate the convergence difficulty for doubly infinite matrices. The notebook does not itself pose that larger question.',[S],area='Complex and operator analysis',match='partial')
prob('GP-1977-21','Selecting combinations with prescribed inner divisors',r'For fixed inner \(\omega\) and a finite family in \(H^\infty\), find a constant-coefficient linear combination whose common inner divisor with \(\omega\) equals that of the whole family; determine the exceptional parameters for a one-parameter family.',['1977-433.6','1977-433.7'],r'Known before the talk: Sherman\textquotesingle s two-function lemma is printed with proof in Sz.-Nagy (1976), and the same paper proves a simultaneous countable-row extension with summable coefficients. As of 10 November 2026, no new open problem is inferred from the expository statement.',[S])
save()
begin(434)
item(434,'P000736','definition','The KP normalization in the notes',r'The equation is \(\frac34u_{yy}+\partial_x\{u_t+\frac14(6uu_x+u_{xxx})\}=0\).',r'The recorded equation is \(3u_{yy}+(4u_t+6uu_x+u_{xxx})_x=0\), over complex variables when rational poles are considered. Rescalings or imaginary changes of \(y\) change the sign and strength of the corresponding particle interaction.',r'\citet[\S3]{'+R+r'} print this normalization. The paper was received 6 September 1977 and appeared in the first issue of 1978; receipt is not evidence of public circulation.',[R],cls='A',area='Integrable systems',literal='correct')
item(434,'P000737','theorem','The double-pole form of rational decaying KP solutions',r'Every rational solution decreasing as \(x\to\infty\) is written as \(-2\sum_i(x-x_i(y,t))^{-2}\).',r'On a parameter domain where poles are distinct, a rational KP solution tending to zero as \(x\to\infty\) has only double poles, zero simple-pole coefficients and leading coefficient \(-2\): \(u=-2\sum_{i=1}^N(x-q_i(y,t))^{-2}\). The pole coordinates can collide at exceptional parameters; a global assertion must allow the resulting limiting rational function.',r'\citet[\S3, Theorem~3]{'+R+r'} give the rational-solution characterization together with the associated Baker--Akhiezer function.',[R],cls='A',area='Integrable systems',problem='GP-1977-22')
item(434,'P000737','claim','The particle Hamiltonian needs a normalization correction',r'The \(y\)-motion is assigned to \(H=\frac12\sum p_i^2+\sum_{i<j}(x_i-x_j)^{-2}\).',r'For precisely the displayed KP equation, the ansatz \(u=-2\sum(x-q_i)^{-2}\), and canonical momenta \(p_i=q_{i,y}\), Laurent coefficients give \(q_{i,yy}=-8\sum_{j\ne i}(q_i-q_j)^{-3}\). Thus one consistent canonical Hamiltonian is \(H=\frac12\sum p_i^2-4\sum_{i<j}(q_i-q_j)^{-2}\). Other standard Calogero conventions follow by rescaling or complexifying time and momenta; they must be stated.',r'\citet[\S2, Theorem~2 and \S3, Corollary~1]{'+R+r'} establish the pole/particle correspondence, but the displayed positive interaction coefficient in that paper is also not literally the canonical Hamiltonian above. The correspondence is exact; the numerical identification in the notebook is not.',[R],cls='A',area='Integrable systems',literal='false as written',match='partial',reconstruction=r'The canonical convention \(p=q_y\) and the corrected coefficient are an editorial Laurent calculation. A different convention might explain the speaker\textquotesingle s numerical coefficient, but none is recorded.',development='annotated',problem='GP-1977-22')
item(434,'P000737','theorem','The KP time is a higher commuting particle flow',r'The \(t\)-dependence is governed by a second commuting integral of the same particle system.',r'In the same canonical convention, pole cancellation gives \(q_{i,t}=\frac34p_i^2-3\sum_{j\ne i}(q_i-q_j)^{-2}\). It is the position component of the flow generated by \(K=\frac14\sum_i p_i^3-3\sum_{i<j}(p_i+p_j)(q_i-q_j)^{-2}\), which commutes with the Hamiltonian of the preceding item. These compatible flows reconstruct the rational KP solutions where poles remain distinct.',r'\citet[\S3, Theorem~3 and Corollary~1]{'+R+r'} identify the higher flow by a cubic trace invariant. The explicit coefficients here retain the notebook\textquotesingle s KP signs and canonical momenta rather than silently using a differently normalized \(F_3\).',[R],cls='A',area='Integrable systems',reconstruction=r'The normalized Hamiltonian \(K\) is an editorial rewriting of the cubic flow; the notebook only names the additional commuting integral.',match='partial',development='annotated',problem='GP-1977-22')
item(434,'P000737','construction','The differential-operator compatibility representation',r'The notes write \(L_1=\partial_x^2+u\), \(L_2=\partial_x^3+\frac32u\partial_x+u\), and a zero-curvature relation.',r'One consistent pair for the notebook\textquotesingle s KP normalization is \(L=\partial_x^2+u\), \(M=\partial_x^3+\frac32u\partial_x+w\), with \(w=\frac34u_x+\frac34\partial_x^{-1}u_y\), and \([\partial_y-L,\partial_t+M]=0\). The integration constant in \(\partial_x^{-1}u_y\) is fixed by boundary conditions or absorbed in a scalar gauge. The lower coefficient of the third-order operator is a new function \(w\), not simply \(u\).',r'\citet[\S3]{'+R+r'} use a separate \(w\). Their printed time/commutator signs require the same convention check; the pair displayed here has been normalized directly to the equation recorded in the notes.',[R],cls='A',area='Integrable systems',literal='false as written',match='partial',reconstruction=r'The coefficient \(w\) and time sign are supplied by direct compatibility; the source has insufficient normalization information to infer them silently.',development='annotated')
item(434,'P000737','remark','Commutative subalgebras of Weyl skew fields',r'A final proposal concerns commutative subalgebras of \(D_n\), the skew field associated with the Weyl algebra.',r'The fragment suggests studying commutative subalgebras or subfields inside a Weyl skew field by spectral geometry. It specifies neither a class of subalgebras, a rank, a maximality condition, nor an equivalence relation; it is not a stated classification theorem for all \(n\).',r'\citet{'+D+r'} is a contemporary primary lead, received 14 April 1976 and published in 1977, but its title and metadata alone do not verify a general Weyl-skew-field assertion. The notebook proposal remains too short to assign an exact fate.',[D],cls='F',area='Noncommutative algebra',literal='not determinable',match='thematic only',verification='publisher metadata checked',confidence='low',status='As of 10 November 2026, no definite new problem with specified quantifiers can be extracted from this fragment.')
prob('GP-1977-22','Rational decaying KP solutions and commuting pole dynamics',r'Classify solutions of \(3u_{yy}+(4u_t+6uu_x+u_{xxx})_x=0\) rational in \(x\) and vanishing at infinity, through finite-dimensional commuting equations for their poles.',['1977-434.2','1977-434.3','1977-434.4'],r'Krichever\textquotesingle s 1978 Theorem3 and corollaries solve the rational classification in its stated sense. Distinct-pole coordinates require local treatment across collisions, and the source\textquotesingle s particle coefficients must be normalized consistently. Earlier particle-integrability occurrences 1975-372.7 and 1975-372.12 are related background, not the same rational-KP question.',[R])
